"use strict";(self.webpackChunk_servicenow_sdk_docs=self.webpackChunk_servicenow_sdk_docs||[]).push([["516756"],{821014(e){e.exports=JSON.parse('{"tag":{"label":"DatabaseView","permalink":"/sdk/4.13.0/tags/database-view","allTagsPath":"/sdk/4.13.0/tags","count":2,"items":[{"id":"guides/database-view-guide","title":"Database Views","description":"Guide for creating ServiceNow Database Views (sysdbview) using the Fluent API. A Database View is a read-only virtual table that SQL-joins two or more real tables into a single reportable pseudo-table, exposing selected columns from each joined table under a per-table variable prefix. Use it when you need to report across, or build lists/queries on top of, data that already lives in other tables \u2014 a Database View stores no data of its own.","permalink":"/sdk/4.13.0/guides/database-view-guide"},{"id":"api/databaseview-api","title":"DatabaseView","description":"Creates a Database View (sysdbview) \u2014 a read-only virtual table that joins two","permalink":"/sdk/4.13.0/api/databaseview-api"}],"unlisted":false}}')}}]);